def bi(en, es, tag='p', cls='', attrs=''):
    return f'<{tag} class="{cls}" data-en="{e(en, quote=True)}" data-es="{e(es, quote=True)}" {attrs}>{e(en)}</{tag}>'

def link(path,en,es,cls='btn-outline'):
    return bi(en,es,'a',cls,f'href="{BASE+path}"')

def resume():
    return bi('Download Resume','Descargar CV','a','btn-outline resume-link',f'href="{BASE}Diego_Armando_Mendez_Resume.pdf" download="Diego_Armando_Mendez_Resume.pdf"')

def title(en,es,tag='// professional ecosystem'):
    return f'<header class="page-heading"><p class="sec-tag">{e(tag)}</p>{bi(en,es,"h1","sec-title")}</header>'

def band(en,es,body,id=''):
    return f'<section class="content-band" id="{id}">{bi(en,es,"h2","band-title")}{body}</section>'

def tags(values):
    return '<div class="tl-tags">'+''.join(f'<span class="tag tag-b">{e(v)}</span>' for v in values)+'</div>'

def record(r):
    body='<ul class="tl-bullets">'+''.join(bi(*b,'li') for b in r['bullets'])+'</ul>' if 'bullets' in r else bi(*r['summary'],'p','record-summary')
    return '<article class="tl-item'+(' omega-role' if r['company']=='Omega Healthcare' else '')+'"><div class="tl-node" aria-hidden="true"></div>'+bi(r['date'],r.get('esDate',r['date']),'p','tl-date')+bi(r['title'],r['esTitle'],'h3','tl-title')+f'<p class="tl-company">{e(r["company"])}</p>'+tags(r.get('tags',[]))+body+'</article>'

