def project_card(p):
    details=''
    for en,es,key in [('Purpose','Propósito','purpose'),('Diego’s contribution','Contribución de Diego','contribution'),('Current state','Estado actual','outcome'),('Privacy & publication','Privacidad y publicación','privacy')]:details+=bi(en,es,'dt')+bi(*p[key],'dd')
    details+=bi('Tools & methods','Herramientas y métodos','dt')+f'<dd>{e(p["methods"])}</dd>'
    return '<article class="project-card">'+bi(p['status'],p['esStatus'],'p','status-label')+bi(p['en'],p['es'],'h3')+bi(p['category'],p['esCategory'],'p','category-label')+bi(*p['summary'])+'<details>'+bi('Project record','Ficha del proyecto','summary')+'<dl>'+details+'</dl></details></article>'

def project_preview():return '<div class="project-grid">'+''.join(project_card(p) for p in projects[:2])+'</div>'

def form(kind):
    commercial=kind=='commercial'
    id='RWWL8j' if commercial else 'Eqq0WA'
    intro=bi('Business inquiry','Consulta comercial','h2') if commercial else bi('Send a Message or Document','Enviar un mensaje o documento','h2')
    if commercial:
        intro+=bi('Email, solution type, and a detailed project description are required. Organization, links, file attachment, and future-contact consent are optional.','El correo, el tipo de solución y una descripción detallada son obligatorios. Organización, enlaces, archivo y consentimiento para contacto futuro son opcionales.')
        intro+=bi('Describe your context, current situation, desired outcome, scope, and urgency. Additional information may be required. An inquiry does not guarantee acceptance, availability, price, or results.','Describe contexto, situación actual, resultado deseado, alcance y urgencia. Puede requerirse información adicional. La consulta no garantiza aceptación, disponibilidad, precio ni resultados.')
        intro+=bi('Your email is used to reply to this inquiry. The optional consent checkbox separately authorizes retaining your details for future communications.','Tu correo se usa para responder esta consulta. La casilla de consentimiento opcional autoriza por separado conservar tus datos para comunicaciones futuras.')
    else:
        intro+=bi('General messages and feedback. Attach a PDF, DOCX, JPG, or PNG up to 10 MB. Please do not send patient information or confidential employer documents.','Mensajes generales y comentarios. Adjunta PDF, DOCX, JPG o PNG de hasta 10 MB. No envíes información de pacientes ni documentos confidenciales del empleador.')
        intro+=bi('Anonymous does not mean invisible to Tally: technical metadata may be processed under the provider’s policies. Email is intended only for a reply; absolute anonymity is not promised.','Anónimo no significa invisible para Tally: puede procesar metadatos técnicos según sus políticas. El correo está destinado únicamente a una respuesta; no se promete anonimato absoluto.')
        intro+=bi('Provider setting pending: the published form currently requires email despite its optional label. For now, it cannot accept an email-free message.','Ajuste pendiente en Tally: el formulario publicado exige correo aunque su etiqueta dice opcional. Por ahora no admite mensajes sin correo.','p','provider-notice')
    intro+='<p class="form-policy"><a href="https://tally.so/help/privacy-policy" target="_blank" rel="noopener">Tally privacy policy / Política de privacidad</a></p>'
    iframe=f'<iframe data-tally-src="https://tally.so/embed/{id}?alignLeft=1&hideTitle=1&transparentBackground=1&dynamicHeight=1&formEventsForwarding=1" title="{("Business inquiry / Consulta comercial" if commercial else "General message / Mensaje general")}" width="100%" height="850" loading="lazy" frameborder="0"></iframe>'
    return '<section class="form-section" aria-label="'+('Commercial inquiry' if commercial else 'General contact')+'">'+intro+iframe+bi('Open the form directly','Abrir el formulario directamente','a','form-fallback',f'href="https://tally.so/r/{id}" target="_blank" rel="noopener"')+'</section>'

